import type { EngineInterface, Register } from 'claude-code'

const PANE = 'focus-ring'
const ITEMS = [
  'alpha', 'alpine', 'amber', 'anchor', 'apple', 'apricot', 'arrow', 'aspen',
  'atlas', 'aurora', 'autumn', 'avenue', 'azure', 'badger', 'basil', 'beacon',
]
const LOG_ROWS = 8

// Module state is enough for a repro; a hot reload resets it.
const state = { text: '', log: false, lines: [] as string[], focused: null as boolean | null, polling: false }

export const filtered = (text: string): string[] => ITEMS.filter(i => i.startsWith(text.toLowerCase()))

function note($: Pick<EngineInterface, 'ui'>, line: string): void {
  state.lines = [...state.lines, line].slice(-LOG_ROWS)
  $.ui.invalidate('ui.render')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'focus-ring', description: 'Open the focus ring repro pane' })
    return next(e)
  })

  on('command.run', { command: 'focus-ring' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Focus ring', focus: true })
    if (!state.polling) {
      state.polling = true
      // Opt-in log source 1: the pane's isFocused, polled.
      $.clock.every(100, async () => {
        if (!state.log) return
        const pane = (await $.ui.panes()).find(p => p.id === PANE)
        const focused = pane ? pane.isFocused : null
        if (focused !== state.focused) {
          state.focused = focused
          note($, `isFocused=${focused}`)
        }
      })
    }
    return { text: 'Focus ring pane opened. Type a letter, e.g. "a", then "al", "alp".' }
  })

  // Opt-in log source 2: each ui.input the pane's Input raises.
  on('ui.input', { requestId: PANE }, ($, e, next) => {
    if (state.log) note($, `ui.input ${e.element} ${e.kind} len=${e.value.length}`)
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    const { Box, Text, Input, Button } = $.ui.resolve(e)
    const rows = filtered(state.text)
    return (
      <Box flexDirection="column">
        <Text dimColor>Type a prefix. The list below shrinks with each key.</Text>
        <Input
          key="filter"
          autoFocus
          placeholder="filter"
          value=""
          onInput={v => {
            state.text = v
            $.ui.invalidate('ui.render')
          }}
          onSubmit={() => {}}
        />
        <Text dimColor>{rows.length} match(es)</Text>
        {rows.map(name => (
          <Button key={`row:${name}`} onPress={() => $.ui.log(`pressed ${name}`)}>
            {name}
          </Button>
        ))}
        <Button
          key="log"
          onPress={() => {
            state.log = !state.log
            state.lines = []
            state.focused = null
            $.ui.invalidate('ui.render')
          }}
        >
          log: {state.log ? 'on' : 'off'}
        </Button>
        {state.log && (
          <Box flexDirection="column" height={LOG_ROWS}>
            {state.lines.map((l, i) => (
              <Text key={`l${i}`} dimColor>{l}</Text>
            ))}
          </Box>
        )}
      </Box>
    )
  })
}

